{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-tps1",
  "version": "0.1.2",
  "description": "Displays live TPS (tokens per second), average TPS, and TTFT (time to first token) in the OpenCode 1.x TUI session prompt.",
  "repository": {
    "type": "git",
    "url": "https://github.com/fengye110/opencode-tps1"
  },
  "license": "MIT",
  "type": "module",
  "exports": {
    ".": "./tui.tsx",
    "./tui": "./tui.tsx",
    "./package.json": "./package.json"
  },
  "files": [
    "README.md",
    "LICENSE",
    "tui.tsx",
    "src/metrics.ts"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "tps",
    "tokens-per-second",
    "ttft",
    "plugin"
  ],
  "engines": {
    "opencode": ">=1.14"
  },
  "dependencies": {
    "@opentui/solid": "0.5.8",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.15",
    "@opentui/core": "0.5.8",
    "typescript": "^5.9.2"
  }
}
